/bin/bash -lc "cat > /workspace/openai_client.py << 'EOF'
import http.client
import json

class OpenAIClient:
    def __init__(self, api_key, api_base=\"api.openai.com\", api_version=\"v1\"):
        self.api_key = api_key
        self.api_base = api_base
        self.api_version = api_version

    def _headers(self):
        return {
            \"Content-Type\": \"application/json\",
            \"Authorization\": f\"Bearer {self.api_key}\"
        }

    def send_prompt(self, prompt, model=\"text-davinci-003\"):
        connection = http.client.HTTPSConnection(self.api_base)
        endpoint = f\"/{self.api_version}/completions\"

        payload = json.dumps({
            \"model\": model,
            \"prompt\": prompt,
            \"max_tokens\": 150
        })

        connection.request(\"POST\", endpoint, body=payload, headers=self._headers())
        response = connection.getresponse()
        data = response.read()
        connection.close()

        return json.loads(data.decode(\"utf-8\"))
EOF
"

